/**
 * Sums amountMinor per currency.
 * Returns an object such as { USD: 1250, EUR: 900 }.
 */
export function monthlyTotals(invoices) {
  const totals = {};
  for (const invoice of invoices) {
    totals[invoice.currency] = (totals[invoice.currency] ?? 0) + invoice.amountMinor;
  }
  return totals;
}
